with src as (select *, if(is_flagged, 'Yes', 'No') is_flagged_label from transactions where account_id in (7, 27)), amount_bucket_summary as (select case when amount >= 4100 then 'high' when amount >= 1400 then 'mid' else 'low' end amount_bucket, sum(case when merchant = 'Lazada' then 1 else 0 end) lazada_count, avg(amount) avg_amount from src group by case when amount >= 4100 then 'high' when amount >= 1400 then 'mid' else 'low' end) select * from amount_bucket_summary;
